/*
星空免费小说	https://api-bc.zonghengxiaoshuo.com
熊猫脑洞小说
https://api-bc.xmxsapp.com
七猫免费小说
https://api-bc.wtzw.com
*/
api_Params = {
	"imei_ip":"",
	"book_privacy":"1",
	"read_preference":"0"
	};

	function sign($){
		s = $.replace(/&/g,"") + "d3dGiJc651gSQ8w1";
		return String(java.md5Encode(s));
	};

	function body($){
		if(!/app/.test(JSON.stringify($))){
			if(/chapter/.test(link_Urlpath)){
				api_Params = {};}
			$ = Object.assign(api_Params, $);}
		else { $ = $;}
	s = Object.keys($).sort().map(key=>key+"="+$[key]).join('&');
		return String(s);
	};

if(headers==""){
  link_Params.sign = sign(body(link_Params));
  burl = source.getKey();
  if(/chapter/.test(link_Urlpath)){
				burl = burl.replace("api-bc","api-ks");}
  url = burl + link_Urlpath + body(link_Params);
  }

