function getVariable(name) {
  const {source} = this;
  let obj = {status: 0, word: 0, sort: 0};
  try {
    obj = JSON.parse(source.getVariable());
  } catch(e) {
    source.setVariable(JSON.stringify(obj));
  }
  if (!name) return obj;
  return obj[name];
}

AES_KEY = 'dzkjgfyxgshylgzm'
AES_IV = 'apiupdownedcrypt'

// 请求体hex加密
function K(bArr) {
  let sb = '';
  for (let b of bArr) {
    let i = b & 255;
    let l = i.toString(16);
    if (i < 16) {
      sb += '0';
    }
    sb += l;
  }
  return sb;
}

// 响应体解密
function v(c) {
  return "0123456789ABCDEF".indexOf(c);
}
function U(str) {
  if (str === null || str === "") {
    return null;
  }
  const upperCase = str.toUpperCase();
  const length = Math.floor(upperCase.length / 2);
  const charArray = upperCase.split('');
  const bArr = new Uint8Array(length);

  for (let i = 0; i < length; i++) {
    const i2 = i * 2;
    bArr[i] = v(charArray[i2 + 1]) | (v(charArray[i2]) << 4);
  }
  return bArr;
}

function M(hexStr) {
    if (!hexStr) {
        return null;
    }
    let byteLength = hexStr.length / 2;
    let bytes = new Uint8Array(byteLength);
    for (let i = 0; i < byteLength; i++) {
        let hexPair = hexStr.substr(i * 2, 2);
        bytes[i] = parseInt(hexPair, 16);
    }
    return bytes
}

// 实现utf8Array转String
function array2str(utf8Array) {
  let result = '';
  for (let i = 0; i < utf8Array.length; i++) {
    let byte = utf8Array[i];
    if (byte < 0x80) {
      // 单字节字符
      result += String.fromCharCode(byte);
    } else if ((byte & 0xE0) === 0xC0) {
      // 两个字节字符
      let charCode = (byte & 0x1F) << 6 | (utf8Array[i + 1] & 0x3F);
      result += String.fromCharCode(charCode);
      i++; // 跳过下一个字节
    } else if ((byte & 0xF0) === 0xE0) {
      // 三个字节字符
      let charCode = (byte & 0x0F) << 12 | (utf8Array[i + 1] & 0x3F) << 6 | (utf8Array[i + 2] & 0x3F);
      result += String.fromCharCode(charCode);
      i += 2; // 跳过下两个字节
    } else if ((byte & 0xF8) === 0xF0) {
      // 四个字节字符
      // 这里不处理四个字节以上的字符，因为它们不在UTF-8范围内
      throw new Error('Invalid UTF-8 byte sequence');
    }
  }
  return result;
}

function randomHex(length) {
  let char = '0123456789abcdef'
  let r = ''
  for (let i = 0; i < length; i++) {
    r += char[Math.ceil(Math.random() * 15)]
  }
  return r
}

function randomStr(length) {
  let char = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'
  let r = ''
  for (let i = 0; i < length; i++) {
    r += char[Math.ceil(Math.random() * 15)]
  }
  return r
}

function time(date) {
  if (typeof date === 'undefined') date = new Date()
  const year = date.getFullYear();
  const month = (date.getMonth() + 1).toString().padStart(2, '0');
  const day = date.getDate().toString().padStart(2, '0');
  const hours = date.getHours().toString().padStart(2, '0');
  const minutes = date.getMinutes().toString().padStart(2, '0');
  const seconds = date.getSeconds().toString().padStart(2, '0');
  const milliseconds = date.getMilliseconds().toString().padStart(3, '0');
  return `${year}${month}${day}${hours}${minutes}${seconds}${milliseconds}`;
}

function decrypt(body) {
  const { java } = this
  if (body.startsWith('<')) return body
  let data = JSON.parse(body).data
  if (!data) return body
  return java.createSymmetricCrypto('AES/CBC/Pkcs7Padding', AES_KEY, AES_IV).decryptStr(java.hexDecodeToByteArray(data))
}

function buildRequestUrl(cmd, data) {
  const { java } = this
  data = K(Array.from(java.createSymmetricCrypto('AES/CBC/Pkcs7Padding', AES_KEY, AES_IV).encrypt(JSON.stringify(data))))
  return `/asg-portal/portal/client/${cmd},{"method": "post", body: "${data}"}`
}

