// 请求体hex加密
function K(bArr) {
  let sb = '';
  for (let b of bArr) {
    let i = b & 255;
    let l = i.toString(16);
    if (i < 16) {
      sb += '0';
    }
    sb += l;
  }
  return sb;
}

